import sys

def solve():
    # Read input from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    A = int(input_data[0])
    B = int(input_data[1])
    C = int(input_data[2])

    # Check if it's possible to divide into two or more groups with equal sums
    # We need to check all possible partitions of 3 numbers into 2 or more groups

    # Case 1: Two groups
    # Possible partitions: {A, B} vs {C}, {A, C} vs {B}, {B, C} vs {A}
    total = A + B + C

    # For two groups, total must be even
    if total % 2 == 0:
        # Check if any pair sums to total/2
        if (A + B == total // 2) or (A + C == total // 2) or (B + C == total // 2):
            print("Yes")
        else:
            print("No")
    else:
        print("No")

    # Case 2: Three groups
    # Each group must have equal sum
    if total % 3 == 0:
        # Each group must sum to total // 3
        # Since we have 3 numbers, each group must be a single number
        if A == B == C == total // 3:
            print("Yes")
        else:
            print("No")
    else:
        print("No")

if __name__ == "__main__":
    solve()
